import json,html
from pathlib import Path
ROOT=Path(__file__).parent
E=lambda s:html.escape(str(s),quote=True)
CURATED={
'R390':'Денис Маршалкин записал, что Иван Петрович работал помощником машиниста паровоза; также отмечена найденная могила.',
'T431':'В записи Фёдора Ивановича приводится свидетельство Мисько В. Н. о жизни в Саратове и работе на авиазаводе. Даты жизни уточнены со слов Виктора Фёдоровича.',
'T204':'Семейная карточка Михаила Фёдоровича прямо называет его доктором химических наук, отмечает работу над родословной и содержит ссылку на биографию РАЕ. Год смерти указан приблизительно: около 2022. Это сопоставление поддержано семейным источником Дениса.',
'P343':'По записанному Денисом рассказу Виктора Бойко, Филипп Ефимович участвовал в Первой мировой войне, побывал в плену и вернулся. Упоминается сохранившаяся семейная фотография 1914 года; само изображение здесь не проверено.',
'P320':'Для Фёклы Ефимовны приведена выписка: рождение 20.09.1873, крещение 23.09.1873; крёстная — Пелагея Ивановна Маршалкина. Архивный ориентир автора: 135-78-636, с. 39 об. Скан требует отдельной сверки.',
'P50':'Для Никифора Васильевича указан брачный документ ГАСК 135-44-771 и прошение отца Василия от 17.01.1884 о разрешении сыну вступить в брак до совершеннолетия. Это указатель к документу, а не просмотренный здесь оригинал.',
'L610':'Денис связывает Фому с Михаилом по исповедной ведомости РГВИА 14877-1-707 за 1848 год. Ранее рассматривалось и отцовство Василия. Новая ссылка помогает проверке существующей связи в древе.',
'P301':'В Familio для Ивана Георгиевича приведена дата смерти 22.10.1979 и отметка о найденной могиле. В исходной карточке сайта был указан только день рождения 05.01.1896. Дата добавлена как сведения источника; в расчёт продолжительности жизни пока не включена.',
'T432':'В Familio пояснено разночтение отчества Марии: первоначально Ивановна, затем исправлено на Михайловна по сообщению Виктора Фёдоровича. В исходной таблице сайта сохранены оба варианта.',
'R96':'Автор Familio сообщает о могиле Фёдора Андреевича на старом Михайловском кладбище рядом с женой Еленой и её сыном от первого брака. Сведения о расположении могил приводятся со слов исследователя.',
'J571':'В записи Силая Евсеевича перечислены варианты имени: Силай, Силуан и Самуил. Это варианты в семейном исследовании, требующие проверки по документам.',
'P137':'По записанным семейным воспоминаниям Александра Григорьевна Павлова воспитывала внука Славика в Верхнерусском; около 1937 года семья уезжала в Баку и позже вернулась. Датировка приблизительная.'}
def section():
 rows=json.loads((ROOT/'familio-candidates.json').read_text('utf8'));people=json.loads((ROOT/'fullPeople.json').read_text('utf8'));by={p['cell']:p for p in people}
 chosen=[]
 for cell,note in CURATED.items():
  matches=[r for r in rows if r['candidates']==[cell]]
  if len(matches)!=1:raise ValueError((cell,len(matches)))
  r=matches[0];chosen.append(dict(cell=cell,name=r['name'],note=note,url='https://familio.org/persons/'+r['uuid']))
 data=[dict(name=r['name'],birth=r['birth'],death=r['death'],url='https://familio.org/persons/'+r['uuid'],candidates=r['candidates'],hasNote=bool(r['bio'])) for r in rows]
 cards=''.join(f'<article><small>{E(x["cell"])}</small><h3>{E(x["name"])}</h3><p>{E(x["note"])}</p><a href="{x["url"]}" target="_blank" rel="noopener">Карточка Familio ↗</a><br><button onclick="window.focusPerson(\'full-{x["cell"]}\')">Открыть в древе ↗</button></article>' for x in chosen)
 result='''<section id="familio-review" class="life-atlas"><small>СВЕРКА ИСТОЧНИКОВ · FAMILIO · 7 НОЯБРЯ 2026</small><h2>Новые подробности семейной истории</h2><p>За каждой ветвью древа — занятия, переезды и семейные воспоминания. Дополнительные записи Дениса Маршалкина в Familio помогают увидеть за именами судьбы: железную дорогу, авиационный завод, науку, военную службу и домашнюю жизнь.</p><div class="family-evidence-grid">'''+cards+'''</div><h3>473 записи Дениса: указатель для сверки</h3><p>Поиск охватывает имена и даты источника. Предложенные карточки дерева подобраны по имени и году рождения и требуют проверки по родственникам. Записи не добавляются автоматически как новые люди; основной счётчик дерева остаётся 903. Остальные 83 записи каталога не отнесены к семье по одной фамилии.</p><label>Найти запись <input id="familio-query" type="search" placeholder="Имя, отчество или год"></label><p id="familio-count" aria-live="polite"></p><div id="familio-results"></div><button id="familio-more">Показать ещё 20</button><p>Новые даты и приблизительные сведения показаны отдельно от исходных дат таблицы и пока не включены в статистику возраста. Подробные заметки доступны по прямым ссылкам на Familio.</p></section><style>#familio-query{font:inherit;padding:12px;max-width:100%;width:380px}#familio-results details{padding:12px 0;border-bottom:1px solid #c9aa77}#familio-results summary{cursor:pointer}#familio-results button{margin:5px;padding:7px;cursor:pointer}#familio-more{padding:12px;margin-top:14px}#familio-review .family-evidence-grid{grid-template-columns:repeat(2,minmax(0,1fr))}@media(max-width:700px){#familio-review .family-evidence-grid{grid-template-columns:1fr}}</style><script>(()=>{const data=DATA,notes=NOTES,q=document.querySelector('#familio-query'),host=document.querySelector('#familio-results'),more=document.querySelector('#familio-more');let limit=20;const norm=s=>s.toLowerCase().replaceAll('ё','е');const el=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n};function draw(){const words=norm(q.value).trim().split(/\s+/),rs=data.filter(r=>words.every(w=>norm([r.name,r.birth,r.death].join(' ')).includes(w)));host.replaceChildren();document.querySelector('#familio-count').textContent='Найдено '+rs.length+' · показано '+Math.min(limit,rs.length);for(const r of rs.slice(0,limit)){const d=el('details','');d.append(el('summary',r.name+' · '+r.birth+' — '+r.death));const a=el('a','Открыть источник Familio ↗');a.href=r.url;a.target='_blank';a.rel='noopener';d.append(a,el('p',r.hasNote?'В источнике есть биографическая заметка.':'Биографическая заметка в каталоге отсутствует.'));if(r.candidates.length)d.append(el('small','Возможные соответствия по имени и году:'));for(const cell of r.candidates){const b=el('button',cell);b.onclick=()=>window.focusPerson('full-'+cell);d.append(b)}host.append(d)}more.hidden=limit>=rs.length}q.oninput=()=>{limit=20;draw()};more.onclick=()=>{limit+=20;draw()};draw();document.addEventListener('personchange',e=>{const n=notes.find(n=>'full-'+n.cell===e.detail.id),c=document.querySelector('#kin-focus .kin-card');if(!n||!c)return;c.append(el('h4','Дополнение из Familio'),el('p',n.note));const a=el('a','Источник: запись Дениса Маршалкина ↗');a.href=n.url;a.target='_blank';a.rel='noopener';c.append(a)})})();</script>'''
 return result.replace('DATA',json.dumps(data,ensure_ascii=False).replace('</','<\\/')).replace('NOTES',json.dumps(chosen,ensure_ascii=False).replace('</','<\\/'))
